import numpy as np

def make(agent=None, objs=(), rewards=()):
    x = np.zeros((10,10,5))
    for r in range(10):
        for c in range(10):
            if r in (0,9) or c in (0,9):
                x[r,c,3] = 1          # wall border
    if agent is not None:
        x[agent[0],agent[1],0] = 1
    for (r,c) in objs:
        x[r,c,1] = 1
    for (r,c) in rewards:
        x[r,c,2] = 1
    # previous frame = current agent+objects (static snapshot)
    if agent is not None:
        x[agent[0],agent[1],4] = 1
    for (r,c) in objs:
        x[r,c,4] = 1
    return x.reshape(-1)

acts = ['noop','up','down','left','right']
names=[]; rows=[]
def add(n, **kw):
    names.append(n); rows.append(make(**kw))

add("walls only")
add("agent(4,4) alone", agent=(4,4))
for a in [(4,1),(4,8),(1,4),(8,4),(1,1),(8,8)]:
    add("agent%s alone"%(a,), agent=a)

dirs = {'U':(3,4),'D':(5,4),'L':(4,3),'R':(4,5),
        'UL':(3,3),'UR':(3,5),'DL':(5,3),'DR':(5,5)}
for d,(r,c) in dirs.items():
    add("agent(4,4)+reward %s"%d, agent=(4,4), rewards=[(r,c)])
for d,(r,c) in dirs.items():
    add("agent(4,4)+object %s"%d, agent=(4,4), objs=[(r,c)])

add("agent(4,4)+reward(4,8)", agent=(4,4), rewards=[(4,8)])
add("agent(4,4)+reward(4,9)", agent=(4,4), rewards=[(4,9)])
for c in [1,4,8]:
    add("agent(4,%d)+reward(4,8)"%c, agent=(4,c), rewards=[(4,8)])

X=np.array(rows)
lg=forward(X)
for n,l in zip(names,lg):
    a=int(np.argmax(l))
    print("%-32s %-5s %s"%(n, acts[a], np.round(l,2)))
